-- اصلاح باگ های جدول انجام شد


CREATE TABLE customer_orders (
    order_id INT PRIMARY KEY,
    customer_id INT,
    username VARCHAR(50),
    first_name NVARCHAR(50),
    last_name NVARCHAR(50),
    birth_date INT, -- فرمت عددی شمسی: YYYYMMDD (مانند 13750512)
    gender VARCHAR(10),
    order_date DATE,
    order_quantity INT, -- تعداد اقلام خریداری‌شده در این سفارش
    order_amount_rial BIGINT, -- مبلغ کل سفارش به ریال
    discount_amount_rial BIGINT, -- مبلغ تخفیف به ریال
    shipping_cost_rial BIGINT, -- هزینه ارسال به ریال
    order_status VARCHAR(20), -- وضعیت سفارش (Completed, Returned, Cancelled)
    payment_method VARCHAR(30) -- درگاه پرداخت، کارت به کارت، کیف پول
);

